W = "https://en.wikipedia.org/wiki/"
def L(key, label, breadth, defn, aliases, see, src, axis="", secs=None):
    return dict(key=key, label=label, breadth=breadth, defn=defn, aliases=aliases, see=see,
                src=[[W + s, "Wikipedia"] for s in src], axis=axis, secs=secs or [])

