def build():
    out = {"subs": []}; code = {}
    for sc, lab, ax, leaves in SUBS:
        s = {"code": sc, "label": lab, "axis": ax, "leaves": []}
        for i, l in enumerate(leaves, 1):
            c = f"{sc}-{i}"; code[l["key"]] = c
            d = {"code": c}
            d.update({k: v for k, v in l.items() if k != "key"})
            if not d["secs"]: d.pop("secs"); d.pop("axis")
            s["leaves"].append(d)
        out["subs"].append(s)
    return out, code
